def components(cells):
    cells=set(cells); seen=set(); best=0
    for c in cells:
        if c in seen: continue
        stack=[c]; n=0; seen.add(c)
        while stack:
            x,y=stack.pop(); n+=1
            for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                p=(x+dx,y+dy)
                if p in cells and p not in seen:
                    seen.add(p); stack.append(p)
        best=max(best,n)
    return best

