from collections import Counter
def solve(g, sep):
    H,W=len(g),len(g[0])
    rows=[i for i,r in enumerate(g) if all(v==sep for v in r)]
    cols=[j for j in range(W) if all(r[j]==sep for r in g)]
    def blocks(idxs,n):
        out=[];start=0
        for i in idxs+[n]:
            if start<i: out.append((start,i))
            start=i+1
        return out
    inner=[g[i][j] for i in range(H) for j in range(W) if g[i][j]!=sep]
    bg=Counter(inner).most_common(1)[0][0]
    def comp(cells):
        cells=set(cells); best=0
        while cells:
            stack=[next(iter(cells))]; cells-= {stack[0]}; n=0
            while stack:
                x,y=stack.pop(); n+=1
                for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                    p=(x+dx,y+dy)
                    if p in cells: cells.discard(p); stack.append(p)
            best=max(best,n)
        return best
    return [[comp([(i,j) for i in range(r0,r1) for j in range(c0,c1) if g[i][j]==bg])
             for c0,c1 in blocks(cols,W)] for r0,r1 in blocks(rows,H)]

